/// Test that match-only parent rules do not create edits (regression test for bug fix)
#[test]
fn test_match_only_parent_rule_no_edit() {
  // Create a match-only rule (no replace_node specified)
  let _match_only_rule = piranha_rule! {
    name = "match_only_parent",
    query = "(
      (binary_expression
          left : (_)* @lhs
          operator:\"&&\"
          right: [(true) (parenthesized_expression (true))]
      )
  @binary_expression)"
    // Note: no replace_node specified, making this a match-only rule
  };
  let match_only_rule = InstantiatedRule::new(&_match_only_rule, &HashMap::new());

  // Verify it's actually a match-only rule
  assert!(match_only_rule.rule().is_match_only_rule());

  let source_code = "class A {
          boolean f = something && true;
        }";

  let mut rule_store = RuleStore::default();
  let args = PiranhaArgumentsBuilder::default()
    .paths_to_codebase(vec![UNUSED_CODE_PATH.to_string()])
    .language(PiranhaLanguage::from(JAVA))
    .build();
  let mut parser = args.language().parser();

  let source_code_unit = SourceCodeUnit::new(
    &mut parser,
    source_code.to_string(),
    &HashMap::new(),
    PathBuf::new().as_path(),
    &args,
  );

  // Range pointing to part of the binary expression that would trigger parent rule matching
  let range = Range {
    start_byte: 41_usize,
    end_byte: 44_usize,
    ..Default::default()
  };

  // Set up match-only rule as a parent rule
  let next_rules = HashMap::from([
    (String::from(PARENT), vec![match_only_rule.clone()]),
    (String::from(PARENT_ITERATIVE), vec![match_only_rule]),
  ]);

  // Before the fix: this would return Some(edit) that deletes content
  // After the fix: this should return Some(identity_edit) that preserves content
  let edit = source_code_unit.get_edit_for_ancestors(&range, &mut rule_store, &next_rules);
  assert!(
    edit.is_some(),
    "Match-only parent rules should create identity edits"
  );

  let edit = edit.unwrap();
  // Verify it's an identity edit (replacement equals original content)
  assert_eq!(
    edit.replacement_string(),
    edit.p_match().matched_string(),
    "Match-only parent rules should create identity edits (no content change)"
  );
}

/// Tests whether comments are preserved when delete_comments is set to false
#[test]
fn test_rule_delete_comments() {
  println!("Starting test...");
  let _rule = piranha_rule! {
    name= "delete_invoc",
    query= "((method_invocation) @m (#eq? @m \"variable.set_value(true)\"))",
    replace_node = "m",
    replace = "",
    keep_comment_regexes = ["// Given .*"]
  };

  let rule = InstantiatedRule::new(&_rule, &HashMap::new());
  let source_code = "class Test {
          public void foobar(){
            // Given something
            // This is an explanatory comment
            // This is another explanatory comment
            variable.set_value(true);
            other_variable.set_value(false);

            // When
            var result = data.Something();

            // Then
            assertTrue(\"This is a test\", result);
          }
        }";

  let mut rule_store = RuleStore::default();

  let args = PiranhaArgumentsBuilder::default()
    .paths_to_codebase(vec![UNUSED_CODE_PATH.to_string()])
    .language(PiranhaLanguage::from(JAVA))
    .cleanup_comments(true)
    .build();
  let mut parser = args.language().parser();

  let mut source_code_unit = SourceCodeUnit::new(
    &mut parser,
    source_code.to_string(),
    &HashMap::new(),
    PathBuf::new().as_path(),
    &args,
  );
  let node = source_code_unit.root_node();
  let matches = source_code_unit.get_matches(&rule, &mut rule_store, node, true);
  assert!(!matches.is_empty());

  let edit = source_code_unit.get_edit(&rule, &mut rule_store, node, true);
  assert!(edit.is_some());
  let edit = edit.unwrap();
  // Apply the edit to the source code unit
  source_code_unit.apply_edit(&edit, &mut parser);

  let edited_code = source_code_unit.code();
  assert!(edited_code.contains("// Given something"));
  assert!(!edited_code.contains("// This is another explanatory comment"));
  assert!(!edited_code.contains("// This is an explanatory comment"));
  assert!(!edited_code.contains("variable.set_value(true);"));
}

