      vec![
        ("to_delete", "flag3: true"),
        (
          "*",
          "{\n        fieldA: \"c\",\n        flag2: true,\n        flag3: true,\n      }",
        ),
      ],
    ],
    GO,
  );
}

#[test]
fn test_escaped_at_symbol() {
  run_test(
    "var x = @something;",
    "var :[name] = \\@something;",
    1,
    vec![vec![("name", "x")]],
    GO,
  );
}

#[test]
fn test_escaped_colon_symbol() {
  run_test(
    "var x = :something;",
    "var :[name] = \\:something;",
    1,
    vec![vec![("name", "x")]],
    GO,
  );
}

